<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreTransportDocumentRequest extends FormRequest {public function authorize():bool{return$this->user()?->can('transporte.documentos.gestionar')??false;}public function rules():array{$c=$this->user()->company_id;return['transport_document_type_id'=>['required',Rule::exists('transport_document_types','id')->where(fn($q)=>$q->where('company_id',$c)->where('is_active',1))],'resource_type'=>'required|in:vehicle,driver,monitor,provider,other','resource_id'=>'nullable|integer','resource_name'=>'nullable|string|max:255','document_number'=>'nullable|string|max:100','issued_at'=>'nullable|date','expires_at'=>'nullable|date|after_or_equal:issued_at','notes'=>'nullable|string|max:2000','supersedes_document_id'=>['nullable',Rule::exists('transport_documents','id')->where(fn($q)=>$q->where('company_id',$c))],'file'=>'nullable|file|mimes:pdf,jpg,jpeg,png|max:10240'];}public function attributes():array{return['transport_document_type_id'=>'tipo de documento','resource_type'=>'tipo de recurso','resource_id'=>'recurso','issued_at'=>'fecha de expedición','expires_at'=>'fecha de vencimiento','file'=>'archivo'];}}
